// b95_smoke_top: smoke design for the Red Pitaya STEMlab 125-14 (original generation, v1.1) (xc7z010clg400-1).
// Generated by tools/board_smoke.py from boards/redpitaya_stemlab_125_14/board.yaml. Do not edit: change the board file and regenerate.
// A counter on the board clock drives the LEDs; switches invert LEDs, a button inverts LED 0; where the board has a PL UART
// a banner is sent at 115200 baud about every 1.3 s and the receive line flips the top LED. No LED or button polarity is assumed.

module b95_smoke_top (
    input  logic clk_p,
    input  logic clk_n,
    output logic [7:0] led
);
    localparam int CLK_HZ       = 125000000;
    localparam int CLKS_PER_BIT = (CLK_HZ + 57600) / 115200;
    localparam int TOPB         = 26;   // $clog2(CLK_HZ) - 1: this counter bit toggles about once a second

    logic clk;
    IBUFDS u_clk_ibuf (.I(clk_p), .IB(clk_n), .O(clk));

    logic [TOPB:0] cnt = '0;
    always_ff @(posedge clk) cnt <= cnt + 1'b1;


    always_comb begin
        led[0] = cnt[TOPB - 0];
        led[1] = cnt[TOPB - 1];
        led[2] = cnt[TOPB - 2];
        led[3] = cnt[TOPB - 3];
        led[4] = cnt[TOPB - 4];
        led[5] = cnt[TOPB - 5];
        led[6] = cnt[TOPB - 6];
        led[7] = cnt[TOPB - 7];
    end
endmodule
